using System.Globalization;
using System.Text.Json.Nodes;

namespace VehicleVision.PleasanterTools.DotNetClient.Generator;

/// <summary>history.json と generation.json から、クライアントのコードを作る。</summary>
/// <remarks>出力に入れるのは、識別子・型名・パス・版という事実だけ。Pleasanter のソースの文章やコードは入れない。</remarks>
internal sealed class ClientGenerator
{
    public const string ClientNamespace = "VehicleVision.PleasanterTools.DotNetClient";

    public const string ModelNamespace = ClientNamespace + ".Models";

    private const string Header = """
        // <auto-generated>
        // tools/VehicleVision.PleasanterTools.DotNetClient.Generator が api-surface/history.json と generation.json から生成した。
        // 直接編集しない。再生成: dotnet run --project tools/VehicleVision.PleasanterTools.DotNetClient.Generator -- generate
        // </auto-generated>
        #nullable enable
        """;

    // 手書きの部分と名前が重ならないようにする
    private static readonly HashSet<string> ReservedNames = new(StringComparer.Ordinal)
    {
        "PleasanterApiClient", "PleasanterOptions", "PleasanterResponse", "PleasanterEnvelope", "PleasanterFile",
        "PleasanterBinaryResponse", "PleasanterErrorKind", "Since", "Until", "RenamedFrom", "ValueBefore",
        "SinceAttribute", "UntilAttribute", "RenamedFromAttribute", "ValueBeforeAttribute",
    };

    private static readonly HashSet<string> Keywords = new(StringComparer.Ordinal)
    {
        "abstract", "as", "base", "bool", "break", "byte", "case", "catch", "char", "checked", "class", "const", "continue",
        "decimal", "default", "delegate", "do", "double", "else", "enum", "event", "explicit", "extern", "false", "finally",
        "fixed", "float", "for", "foreach", "goto", "if", "implicit", "in", "int", "interface", "internal", "is", "lock",
        "long", "namespace", "new", "null", "object", "operator", "out", "override", "params", "private", "protected",
        "public", "readonly", "ref", "return", "sbyte", "sealed", "short", "sizeof", "stackalloc", "static", "string",
        "struct", "switch", "this", "throw", "true", "try", "typeof", "uint", "ulong", "unchecked", "unsafe", "ushort",
        "using", "virtual", "void", "volatile", "while",
    };

    private static readonly Dictionary<string, string> Primitives = new(StringComparer.Ordinal)
    {
        ["string"] = "string", ["String"] = "string", ["bool"] = "bool", ["Boolean"] = "bool",
        ["int"] = "int", ["Int32"] = "int", ["long"] = "long", ["Int64"] = "long", ["short"] = "short",
        ["byte"] = "byte", ["decimal"] = "decimal", ["Decimal"] = "decimal", ["double"] = "double", ["float"] = "float",
        ["DateTime"] = "global::System.DateTime", ["DateTimeOffset"] = "global::System.DateTimeOffset",
        ["TimeSpan"] = "global::System.TimeSpan", ["Guid"] = "global::System.Guid",
        ["object"] = "object", ["Object"] = "object", ["dynamic"] = "object",
    };

    private readonly History _history;
    private readonly GenerationConfig _config;
    private readonly List<EndpointPlan> _endpoints = [];
    private readonly SortedDictionary<string, string> _excluded = new(StringComparer.Ordinal);
    private readonly ModelPlan _models;

    public ClientGenerator(History history, GenerationConfig config)
    {
        _history = history;
        _config = config;
        Validate();
        foreach (var item in history.Endpoints)
        {
            var key = item.Key["endpoint:".Length..];
            var area = (string?)item.Latest["area"] ?? string.Empty;
            if (_config.ExcludedAreas.TryGetValue(area, out var areaReason))
            {
                _excluded[key] = areaReason;
            }
            else if (_config.ExcludedEndpoints.TryGetValue(key, out var reason))
            {
                _excluded[key] = reason;
            }
            else
            {
                _endpoints.Add(EndpointPlan.From(item));
            }
        }

        var roots = _endpoints.SelectMany(e => e.RequestTypes.Concat(e.ModelTypes)).Concat(_config.ExtraTypes).Distinct(StringComparer.Ordinal);
        _models = new ModelPlan(history, config, roots);
        var clash = _models.TopLevel.Select(t => t.Identifier)
            .Concat(ResponseClasses().Select(r => r.Name))
            .FirstOrDefault(n => ReservedNames.Contains(n) || Groups().Any(g => g + "Operations" == n));
        if (clash is not null)
        {
            throw new GenerationException($"型の名前 {clash} が、手書きの部分か API のクラスと重なります。");
        }
    }

    /// <summary>生成するエンドポイント（キーの順）。</summary>
    public IReadOnlyList<EndpointPlan> Endpoints => [.. _endpoints.OrderBy(e => e.Key, StringComparer.Ordinal)];

    /// <summary>対象外のエンドポイントと理由。</summary>
    public IReadOnlyDictionary<string, string> Excluded => _excluded;

    /// <summary>生成するファイル（出力先からの相対パス → 中身）。</summary>
    public SortedDictionary<string, string> Generate()
    {
        var files = new SortedDictionary<string, string>(StringComparer.Ordinal);
        foreach (var type in _models.TopLevel)
        {
            files[$"Models/{type.Identifier}.g.cs"] = ModelFile(type);
        }

        foreach (var (name, endpoints) in ResponseClasses())
        {
            files[$"Responses/{name}.g.cs"] = ResponseFile(name, endpoints);
        }

        foreach (var group in Groups())
        {
            files[$"Operations/{group}Operations.g.cs"] = ApiFile(group);
        }

        files["PleasanterApiClient.g.cs"] = ClientFile();
        files["GeneratedSurface.g.cs"] = SurfaceFile();
        foreach (var (path, text) in files)
        {
            if (text.Contains("Implem.", StringComparison.Ordinal))
            {
                throw new GenerationException($"{path} に Pleasanter の名前空間（Implem.）が入りました。参照の分離の検査に通りません。");
            }
        }

        return files;
    }

    /// <summary>Pleasanter のタグを版の文字列にする（<c>Pleasanter_1.4.0.0</c> → <c>1.4.0.0</c>）。</summary>
    public static string VersionOf(string tag) => tag.StartsWith("Pleasanter_", StringComparison.Ordinal) ? tag["Pleasanter_".Length..] : tag;

    /// <summary>Pleasanter の型の名前を、出典として書く形にする（<c>Implem.</c> を除く）。</summary>
    public static string SourceName(string fullName) => fullName.StartsWith("Implem.", StringComparison.Ordinal) ? fullName["Implem.".Length..] : fullName;

    private void Validate()
    {
        if (_history.Tags.Count == 0 || _history.Tags[0] != _config.MinimumVersion)
        {
            throw new GenerationException($"history.json の最初の版（{_history.Tags.FirstOrDefault()}）が、generation.json の minimumVersion（{_config.MinimumVersion}）と違います。");
        }

        var keys = _history.Endpoints.Select(e => e.Key["endpoint:".Length..]).ToHashSet(StringComparer.Ordinal);
        foreach (var key in _config.ExcludedEndpoints.Keys.Where(k => !keys.Contains(k)))
        {
            throw new GenerationException($"generation.json の対象外 {key} が history.json にありません。");
        }

        foreach (var r in _config.Renames)
        {
            var members = _history.Members.GetValueOrDefault(r.Type) ?? [];
            var from = members.FirstOrDefault(m => m.Name == r.From).Item;
            var to = members.FirstOrDefault(m => m.Name == r.To).Item;
            if (from is null || to is null)
            {
                throw new GenerationException($"名前の変更 {r.Type}#{r.From} → {r.To} のメンバーが history.json にありません。");
            }

            if (from.Until != r.Version || to.Since != r.Version)
            {
                throw new GenerationException(
                    $"名前の変更 {r.Type}#{r.From} → {r.To}: 旧い名前の Until（{from.Until}）と新しい名前の Since（{to.Since}）が {r.Version} と合いません。");
            }

            if (TypeText.Parse((string)from.Latest["type"]!).Shape() != TypeText.Parse((string)to.Latest["type"]!).Shape())
            {
                throw new GenerationException($"名前の変更 {r.Type}#{r.From} → {r.To}: 型が違います。");
            }
        }
    }

    private IEnumerable<string> Groups() => _endpoints.Select(e => e.Group).Distinct(StringComparer.Ordinal).Order(StringComparer.Ordinal);

    private IEnumerable<(string Name, List<EndpointPlan> Endpoints)> ResponseClasses()
        => _endpoints
            .Where(e => e.Response == ResponseKind.Envelope)
            .GroupBy(e => e.Group + e.Action + "Response", StringComparer.Ordinal)
            .OrderBy(g => g.Key, StringComparer.Ordinal)
            .Select(g =>
            {
                var list = g.OrderBy(e => e.Key, StringComparer.Ordinal).ToList();
                if (list.Select(e => string.Join(",", e.GetMembers)).Distinct(StringComparer.Ordinal).Count() > 1)
                {
                    throw new GenerationException($"{g.Key}: 同じアクションで、応答のメンバーが違います。");
                }

                return (g.Key, list);
            });

    private static string Since(HistoryItem item) => VersionOf(item.Since);

    private static string? Until(HistoryItem item) => item.Until is null ? null : VersionOf(item.Until);

    private static void VersionAttributes(CodeWriter w, HistoryItem item, string? sinceOverride = null)
    {
        if (item.HasIntervals)
        {
            throw new GenerationException($"{item.Key}: 途中で無くなって戻った項目（intervals）は扱えません。");
        }

        w.Line($"[Since(\"{sinceOverride ?? Since(item)}\")]");
        if (Until(item) is { } until)
        {
            w.Line($"[Until(\"{until}\")]");
        }
    }

    private static string VersionText(HistoryItem item)
    {
        var since = Since(item);
        var text = since == "1.4.0.0" ? "Pleasanter 1.4.0.0 以前から在る" : $"Pleasanter {since} から在る";
        return Until(item) is { } until ? $"{text}（{until} からは無い）" : text;
    }

    private string ModelFile(TypePlan type)
    {
        var w = new CodeWriter();
        foreach (var line in Header.Split('\n'))
        {
            w.Line(line);
        }

        w.Line("#pragma warning disable CS1591 // メンバーの説明は、Pleasanter のメンバー名と版の属性だけにする");
        w.Line();
        w.Line("using System.Text.Json.Serialization;");
        w.Line();
        w.Line($"namespace {ModelNamespace};");
        w.Line();
        WriteType(w, type);
        return w.ToString();
    }

    private void WriteType(CodeWriter w, TypePlan type)
    {
        w.Line($"/// <summary>Pleasanter の型 <c>{CodeWriter.Xml(SourceName(type.FullName))}</c>。{VersionText(type.Item)}。</summary>");
        if (type.Kind == TypeKind.Enum)
        {
            WriteEnum(w, type);
            return;
        }

        w.Line("/// <remarks>");
        w.Line("/// <para>すべてのメンバーは null を取れる。null のメンバーは送らない（サーバー側の既定値に任せる）。</para>");
        w.Line("/// <para>値の入ったメンバーが接続先の版で使えなければ、送る前に <see cref=\"PleasanterVersionNotSupportedException\"/> になる。</para>");
        w.Line("/// </remarks>");
        VersionAttributes(w, type.Item);
        var baseClause = type.Base is { } b ? " : " + ModelPlan.Qualified(_models.Get(b)) : string.Empty;
        w.Open($"public partial class {type.Identifier}{baseClause}");
        var first = true;
        foreach (var nested in type.Nested.OrderBy(n => n.Identifier, StringComparer.Ordinal))
        {
            if (!first)
            {
                w.Line();
            }

            WriteType(w, nested);
            first = false;
        }

        var inherited = InheritedMembers(type);
        var nestedNames = type.Nested.Select(n => n.Identifier).ToHashSet(StringComparer.Ordinal);
        var renames = _config.Renames.Where(r => r.Type == type.FullName).ToList();
        foreach (var (name, member) in _models.SerializedMembers(type.FullName))
        {
            if (renames.Any(r => r.From == name))
            {
                continue; // 新しい名前のメンバーにまとめる
            }

            if (!first)
            {
                w.Line();
            }

            first = false;
            var value = member.Latest;
            CheckTypeChanges(member);
            var (csType, untyped) = RenderType(TypeText.Parse((string)value["type"]!), RefsOf(value), top: true);
            if (untyped)
            {
                w.Line($"/// <summary>型付けしていない（Pleasanter の型 <c>{CodeWriter.Xml((string)value["type"]!)}</c> が、生成の対象に無い）。</summary>");
            }

            var rename = renames.FirstOrDefault(r => r.To == name);
            if (rename is not null)
            {
                var old = _models.SerializedMembers(type.FullName).First(m => m.Name == rename.From).Item;
                w.Line($"/// <summary>{VersionOf(rename.Version)} より前の名前は <c>{rename.From}</c>（旧い版へは旧い名前で送る）。</summary>");
                w.Line($"[Since(\"{Since(old)}\")]");
                if (Until(member) is { } until)
                {
                    w.Line($"[Until(\"{until}\")]");
                }

                w.Line($"[RenamedFrom(\"{rename.From}\", \"{VersionOf(rename.Version)}\")]");
            }
            else
            {
                VersionAttributes(w, member);
            }

            var jsonName = ModelPlan.JsonName(value);
            var property = name;
            if (property == type.Identifier || nestedNames.Contains(property))
            {
                jsonName ??= name;
                property += "Value";
            }

            if (jsonName is not null)
            {
                w.Line($"[JsonPropertyName({CodeWriter.Literal(jsonName)})]");
            }

            var modifier = inherited.Contains(property) ? "new " : string.Empty;
            w.Line($"public {modifier}{csType} {Identifier(property)} {{ get; set; }}");
        }

        w.Close();
    }

    private void WriteEnum(CodeWriter w, TypePlan type)
    {
        var bases = type.Item.Latest["bases"]?.AsArray().Select(b => (string)b!).ToList() ?? [];
        var underlying = bases.FirstOrDefault(b => b is "long" or "short" or "byte" or "uint" or "ulong");
        VersionAttributes(w, type.Item);
        w.Open($"public enum {type.Identifier}{(underlying is null ? string.Empty : " : " + underlying)}");
        var values = (_history.EnumValues.GetValueOrDefault(type.FullName) ?? [])
            .Select(v => (v.Name, v.Item, Number: NumberOf(v.Item.Latest["value"], v.Item.Key)))
            .OrderBy(v => v.Number)
            .ThenBy(v => v.Name, StringComparer.Ordinal)
            .ToList();
        var first = true;
        foreach (var (name, item, number) in values)
        {
            if (!first)
            {
                w.Line();
            }

            first = false;
            VersionAttributes(w, item);
            for (var i = 0; i < item.Revisions.Count - 1; i++)
            {
                var before = NumberOf(item.Revisions[i].Value?["value"], item.Key);
                w.Line($"[ValueBefore(\"{VersionOf(item.Revisions[i + 1].Since)}\", {before.ToString(CultureInfo.InvariantCulture)})]");
            }

            w.Line($"{Identifier(name)} = {number.ToString(CultureInfo.InvariantCulture)},");
        }

        w.Close();
    }

    private static decimal NumberOf(JsonNode? value, string key)
        => value is JsonValue v && decimal.TryParse(v.ToJsonString(), NumberStyles.Float, CultureInfo.InvariantCulture, out var d)
            ? d
            : throw new GenerationException($"{key}: 列挙値の数値が取れていません（{value?.ToJsonString() ?? "null"}）。");

    private HashSet<string> InheritedMembers(TypePlan type)
    {
        var names = new HashSet<string>(StringComparer.Ordinal);
        for (var b = type.Base; b is not null; b = _models.Get(b).Base)
        {
            foreach (var (name, _) in _models.SerializedMembers(b))
            {
                names.Add(name);
            }
        }

        return names;
    }

    private static void CheckTypeChanges(HistoryItem member)
    {
        var shapes = member.Revisions.Select(r => TypeText.Parse((string)r.Value!["type"]!).Shape()).Distinct(StringComparer.Ordinal).ToList();
        if (shapes.Count > 1)
        {
            throw new GenerationException($"{member.Key}: 版で型が変わります（{string.Join(" → ", shapes)}）。扱いを決めてから生成する。");
        }
    }

    private static List<string> RefsOf(JsonNode value) => value["typeRefs"]?.AsArray().Select(r => (string)r!).ToList() ?? [];

    /// <summary>型を C# で書く。型付けできないもの（生成の対象に無い型）は <c>JsonElement</c> にし、印を返す。</summary>
    private (string Text, bool Untyped) RenderType(TypeText t, IReadOnlyList<string> refs, bool top)
    {
        var untyped = false;
        string core;
        if (Primitives.TryGetValue(t.Name, out var primitive))
        {
            core = primitive;
        }
        else if (t.Name is "List" or "IList" or "IEnumerable" or "ICollection" or "IReadOnlyList" or "IReadOnlyCollection" && t.Arguments.Count == 1)
        {
            var (arg, u) = RenderType(t.Arguments[0], refs, top: false);
            core = $"global::System.Collections.Generic.List<{arg}>";
            untyped |= u;
        }
        else if (t.Name is "HashSet" or "ISet" && t.Arguments.Count == 1)
        {
            var (arg, u) = RenderType(t.Arguments[0], refs, top: false);
            core = $"global::System.Collections.Generic.HashSet<{arg}>";
            untyped |= u;
        }
        else if (t.Name is "Dictionary" or "IDictionary" or "IReadOnlyDictionary" && t.Arguments.Count == 2)
        {
            var (key, u1) = RenderType(t.Arguments[0], refs, top: false);
            var (value, u2) = RenderType(t.Arguments[1], refs, top: false);
            // JSON のキーは文字列なので、object のキーは string で受ける
            key = key.TrimEnd('?');
            core = $"global::System.Collections.Generic.Dictionary<{(key == "object" ? "string" : key)}, {value}>";
            untyped |= u1 | u2;
        }
        else
        {
            var target = refs.FirstOrDefault(r => r == t.Name || r.EndsWith("." + t.Name, StringComparison.Ordinal));
            var plan = target is null ? null : _models.Find(target);
            switch (plan?.Kind)
            {
                case TypeKind.Class or TypeKind.Enum:
                    core = ModelPlan.Qualified(plan);
                    break;
                case TypeKind.ListAlias:
                    core = $"global::System.Collections.Generic.List<{ModelPlan.Qualified(_models.Get(plan.ListElement!))}>";
                    break;
                case TypeKind.GenericListAlias when t.Arguments.Count == 1:
                    var (arg, u) = RenderType(t.Arguments[0], refs, top: false);
                    core = $"global::System.Collections.Generic.List<{arg}>";
                    untyped |= u;
                    break;
                default:
                    core = "global::System.Text.Json.JsonElement";
                    untyped = true;
                    break;
            }
        }

        var element = core;
        if (t.Nullable && core != "object")
        {
            element += "?";
        }
        else if (!top && core == "object")
        {
            element = "object?";
        }

        var text = element + string.Concat(Enumerable.Repeat("[]", t.ArrayRanks));
        if (top && !text.EndsWith('?'))
        {
            text += "?";
        }

        return (text, untyped);
    }

    private static string Identifier(string name) => Keywords.Contains(name) ? "@" + name : name;

    private static string Camel(string name)
    {
        var camel = char.ToLowerInvariant(name[0]) + name[1..];
        return Keywords.Contains(camel) ? "@" + camel : camel;
    }

    private string ResponseFile(string name, List<EndpointPlan> endpoints)
    {
        var w = new CodeWriter();
        foreach (var line in Header.Split('\n'))
        {
            w.Line(line);
        }

        w.Line();
        w.Line("using System.Text.Json;");
        w.Line();
        w.Line($"namespace {ModelNamespace};");
        w.Line();
        var keys = string.Join("・", endpoints.Select(e => $"<c>POST {CodeWriter.Xml(e.Path)}</c>"));
        var hints = endpoints.SelectMany(e => e.ModelTypes).Distinct(StringComparer.Ordinal).Order(StringComparer.Ordinal).ToList();
        w.Line($"/// <summary>{keys} の応答の <c>Response</c>。</summary>");
        w.Line("/// <remarks>");
        w.Line("/// <para>**型付けしていない。** 応答は Pleasanter が匿名型で組み立てるため、history.json にはメンバー名しか無い。");
        w.Line("/// 各メンバーは JSON のまま（<see cref=\"JsonElement\"/>）で、型は利用者が選ぶ（<see cref=\"PleasanterApiClient.DeserializeAsync{T}\"/>）。</para>");
        if (hints.Count > 0)
        {
            var hintText = string.Join("・", hints.Select(h => $"<c>{CodeWriter.Xml(_models.Find(h) is { } p ? p.CSharpName : SourceName(h))}</c>"));
            w.Line($"/// <para>手がかり（辿った処理の戻り値の型。<c>Data</c> の要素の型であることが多いが、確かめていない）: {hintText}。</para>");
        }

        w.Line("/// </remarks>");
        w.Open($"public sealed class {name}");
        var first = true;
        foreach (var member in endpoints[0].GetMembers)
        {
            if (!first)
            {
                w.Line();
            }

            first = false;
            w.Line($"/// <summary>応答の <c>{member}</c>（型付けしていない）。</summary>");
            w.Line($"public JsonElement? {Identifier(member)} {{ get; set; }}");
        }

        w.Close();
        return w.ToString();
    }

    private string ApiFile(string group)
    {
        var endpoints = _endpoints.Where(e => e.Group == group).OrderBy(e => e.Action, StringComparer.Ordinal).ThenBy(e => e.Key, StringComparer.Ordinal).ToList();
        var w = new CodeWriter();
        foreach (var line in Header.Split('\n'))
        {
            w.Line(line);
        }

        w.Line();
        w.Line($"using {ModelNamespace};");
        w.Line();
        w.Line($"namespace {ClientNamespace};");
        w.Line();
        w.Line($"/// <summary>Pleasanter の <c>{group}Controller</c> の API。</summary>");
        w.Line("/// <remarks>版で使えないものを呼ぶと、送る前に <see cref=\"PleasanterVersionNotSupportedException\"/> になる（<see cref=\"PleasanterOptions.UnknownServerVersion\"/>）。</remarks>");
        w.Open($"public sealed class {group}Operations");
        w.Line("private readonly PleasanterApiClient _client;");
        w.Line();
        for (var i = 0; i < endpoints.Count; i++)
        {
            var e = endpoints[i];
            w.Line($"private static readonly PleasanterEndpoint Endpoint{i} = new(\"{group}.{e.Action}Async（{e.Key}）\", \"{Since(e.Item)}\", {(Until(e.Item) is { } u ? $"\"{u}\"" : "null")});");
        }

        w.Line();
        w.Line($"internal {group}Operations(PleasanterApiClient client) => _client = client;");
        for (var i = 0; i < endpoints.Count; i++)
        {
            foreach (var variant in Variants(endpoints[i]))
            {
                w.Line();
                WriteMethod(w, endpoints[i], i, variant);
            }
        }

        w.Close();
        return w.ToString();
    }

    /// <summary>本文の型の組み合わせ。レコードの種類の型は、どれか 1 つを選ぶ多重定義にする。</summary>
    private List<(string? Record, List<string> Common)> Variants(EndpointPlan e)
    {
        var records = e.RequestTypes.Where(_config.RecordTypes.Contains).ToList();
        var common = e.RequestTypes.Where(t => !_config.RecordTypes.Contains(t)).ToList();
        return records.Count == 0
            ? [(null, common)]
            : [.. records.Select(r => ((string?)r, common))];
    }

    private static string ParameterName(string typeIdentifier)
    {
        var name = typeIdentifier;
        if (name.EndsWith("ApiModel", StringComparison.Ordinal) && name.Length > "ApiModel".Length)
        {
            name = name[..^"ApiModel".Length];
        }
        else if (name.EndsWith("Api", StringComparison.Ordinal) && name.Length > "Api".Length)
        {
            name = name[..^"Api".Length];
        }

        return Camel(name);
    }

    private void WriteMethod(CodeWriter w, EndpointPlan e, int index, (string? Record, List<string> Common) variant)
    {
        var used = new HashSet<string>(StringComparer.Ordinal) { "cancellationToken" };
        string Unique(string name)
        {
            var candidate = name;
            for (var n = 2; !used.Add(candidate); n++)
            {
                candidate = name + n.ToString(CultureInfo.InvariantCulture);
            }

            return candidate;
        }

        var signature = new List<string>();
        var docs = new List<string>();
        var pathText = e.Path;
        foreach (var r in e.Route)
        {
            var name = Unique(Camel(r.Name));
            var type = r.Type switch
            {
                "long" or "int" or "string" => r.Type,
                _ => throw new GenerationException($"{e.Key}: ルートの引数の型 {r.Type} は扱えません。"),
            };
            signature.Add($"{type} {name}");
            docs.Add($"/// <param name=\"{name.TrimStart('@')}\">ルートの <c>{{{r.Name}}}</c>。</param>");
            pathText = pathText.Replace("{" + r.Name + "}", $"{{PleasanterApiClient.Segment({name})}}", StringComparison.Ordinal);
        }

        // ルートの {controller}・{action} は、ASP.NET の規則でコントローラ名・アクション名になる
        pathText = pathText.Replace("{controller}", e.Group, StringComparison.Ordinal).Replace("{action}", e.Action, StringComparison.Ordinal);
        if (pathText.Replace("{PleasanterApiClient.Segment(", string.Empty, StringComparison.Ordinal).Contains('{', StringComparison.Ordinal))
        {
            throw new GenerationException($"{e.Key}: ルートに、引数で埋められない部分があります（{e.Path}）。");
        }

        string? fileName = null;
        if (e.Transport is Transport.Import or Transport.Upload)
        {
            fileName = Unique("file");
            signature.Add($"PleasanterFile {fileName}");
            docs.Add($"/// <param name=\"{fileName}\">送るファイル。</param>");
        }

        var bodies = new List<string>();
        string? required = null;
        if (variant.Record is { } record)
        {
            var type = _models.Get(record);
            required = Unique(ParameterName(type.Identifier));
            signature.Add($"{type.CSharpName} {required}");
            docs.Add($"/// <param name=\"{required.TrimStart('@')}\">本文（<c>{CodeWriter.Xml(SourceName(record))}</c>）。</param>");
            bodies.Add(required);
        }

        foreach (var common in variant.Common)
        {
            var type = _models.Get(common);
            var name = Unique(ParameterName(type.Identifier));
            signature.Add($"{type.CSharpName}? {name} = null");
            docs.Add($"/// <param name=\"{name.TrimStart('@')}\">本文（<c>{CodeWriter.Xml(SourceName(common))}</c>）。</param>");
            bodies.Insert(bodies.Count - (required is null ? 0 : 1), name); // 共通の型を先に重ね、レコードの型を後に重ねる
        }

        var queries = new List<(string Key, string Name)>();
        foreach (var q in e.Queries)
        {
            var name = Unique(Camel(q.Name));
            signature.Add($"{q.Type} {name} = null");
            docs.Add($"/// <param name=\"{name.TrimStart('@')}\">クエリ文字列の <c>{q.Name}</c>。</param>");
            queries.Add((q.Name, name));
        }

        var forms = new List<(string Key, string Name)>();
        foreach (var f in e.Forms)
        {
            var name = Unique(Camel(f.Name));
            signature.Add($"{f.Type} {name} = null");
            docs.Add($"/// <param name=\"{name.TrimStart('@')}\">フォームの <c>{f.Name}</c>。</param>");
            forms.Add((f.Name, name));
        }

        signature.Add("CancellationToken cancellationToken = default");
        docs.Add("/// <param name=\"cancellationToken\">取り消し。</param>");

        var pathForDoc = e.Path.Replace("{controller}", e.Group, StringComparison.Ordinal);
        var responseClass = e.Group + e.Action + "Response";
        var returnType = e.Response switch
        {
            ResponseKind.Binary => "PleasanterBinaryResponse",
            ResponseKind.Envelope => $"PleasanterResponse<PleasanterEnvelope<{responseClass}>>",
            _ => "PleasanterResponse",
        };

        w.Line($"/// <summary><c>POST {CodeWriter.Xml(pathForDoc)}</c> を呼ぶ。</summary>");
        w.Line("/// <remarks>");
        w.Line($"/// <para>{VersionText(e.Item)}。</para>");
        w.Line($"/// <para>{CodeWriter.Xml(TransportText(e))}</para>");
        if (variant.Record is not null)
        {
            w.Line("/// <para>本文の型は、レコード（サイト）の種類に合うものを選ぶ。history.json の本文の型の和集合から作った多重定義で、その種類で使えるかは確かめていない。</para>");
        }

        w.Line($"/// <para>{ResponseText(e)}</para>");
        var notes = new List<string>();
        if (e.RateLimiting is { } limit)
        {
            notes.Add($"レート制限 <c>{CodeWriter.Xml(limit)}</c>（最新の版での指定）");
        }

        if (e.ChecksPrivilege)
        {
            notes.Add("特権ユーザーかを確かめる");
        }

        if (notes.Count > 0)
        {
            w.Line($"/// <para>{string.Join("。", notes)}。</para>");
        }

        w.Line("/// </remarks>");
        foreach (var d in docs)
        {
            w.Line(d);
        }

        w.Line("/// <exception cref=\"PleasanterVersionNotSupportedException\">接続先の版では使えない。</exception>");
        VersionAttributes(w, e.Item);
        w.Open($"public Task<{returnType}> {e.Action}Async({string.Join(", ", signature)})");
        if (required is not null)
        {
            w.Line($"ArgumentNullException.ThrowIfNull({required});");
        }

        if (fileName is not null)
        {
            w.Line($"ArgumentNullException.ThrowIfNull({fileName});");
        }

        var path = $"$\"{pathText}\"";
        var bodyArray = $"[{string.Join(", ", bodies)}]";
        string List(List<(string Key, string Name)> values) => values.Count == 0
            ? "null"
            : $"[{string.Join(", ", values.Select(v => $"new({CodeWriter.Literal(v.Key)}, {v.Name})"))}]";
        var call = e.Transport switch
        {
            Transport.Import => $"_client.SendImportAsync(Endpoint{index}, {path}, {bodyArray}, {fileName}, cancellationToken)",
            Transport.Upload => $"_client.SendUploadAsync(Endpoint{index}, {path}, {fileName}, {List(queries)}, {List(forms)}, cancellationToken)",
            _ when e.Response == ResponseKind.Binary => $"_client.SendForBinaryAsync(Endpoint{index}, {path}, {bodyArray}, cancellationToken)",
            _ when e.Response == ResponseKind.Envelope => $"_client.SendJsonAsync<PleasanterEnvelope<{responseClass}>>(Endpoint{index}, {path}, {bodyArray}, {List(queries)}, cancellationToken)",
            _ => $"_client.SendJsonAsync(Endpoint{index}, {path}, {bodyArray}, {List(queries)}, cancellationToken)",
        };
        if (e.Transport == Transport.Import && queries.Count > 0)
        {
            throw new GenerationException($"{e.Key}: フォームで送り、クエリ文字列も使う形は扱えません。");
        }

        w.Line($"return {call};");
        w.Close();
    }

    private static string TransportText(EndpointPlan e) => e.Transport switch
    {
        Transport.Import => "フォームの parameters に本文の JSON（ApiKey・ApiVersion を含む）を入れ、ファイルを添付して送る。",
        Transport.Upload => "API キーを Authorization: Bearer で送り、ファイルとフォームの値を送る。1 回で送る形だけを生成している（Content-Range での分割は対象外）。",
        _ when e.RequestTypes.Count == 0 => "本文は ApiKey・ApiVersion だけ（辿った処理が本文を型として読んでいない）。",
        _ => "本文は JSON。複数の型があれば 1 つの本文に重ねる。ApiKey・ApiVersion はクライアントが入れる。",
    };

    private static string ResponseText(EndpointPlan e) => e.Response switch
    {
        ResponseKind.Binary => "応答はファイル。",
        ResponseKind.Envelope => $"応答は包み（StatusCode・LimitPerDate・LimitRemaining・Response）。<c>Response</c> はメンバー名（{string.Join("・", e.GetMembers)}）だけが取れていて、型付けしていない。",
        _ => "応答は型付けしていない（<see cref=\"PleasanterResponse.Body\"/>）。成功・失敗の Id・Message は <see cref=\"PleasanterResponse.Id\"/>・<see cref=\"PleasanterResponse.Message\"/>。",
    };

    private string ClientFile()
    {
        var w = new CodeWriter();
        foreach (var line in Header.Split('\n'))
        {
            w.Line(line);
        }

        w.Line();
        w.Line($"namespace {ClientNamespace};");
        w.Line();
        w.Open("public sealed partial class PleasanterApiClient");
        var first = true;
        foreach (var group in Groups())
        {
            if (!first)
            {
                w.Line();
            }

            first = false;
            var field = "_" + char.ToLowerInvariant(group[0]) + group[1..];
            w.Line($"private {group}Operations? {field};");
            w.Line();
            w.Line($"/// <summary>Pleasanter の <c>{group}Controller</c> の API。</summary>");
            w.Line($"public {group}Operations {group} => {field} ??= new {group}Operations(this);");
        }

        w.Close();
        return w.ToString();
    }

    private string SurfaceFile()
    {
        var w = new CodeWriter();
        foreach (var line in Header.Split('\n'))
        {
            w.Line(line);
        }

        w.Line();
        w.Line($"namespace {ClientNamespace};");
        w.Line();
        w.Line("/// <summary>生成のもとにした API 面の表の範囲と、対象外にしたエンドポイント。</summary>");
        w.Open("public static class GeneratedSurface");
        w.Line("/// <summary>API 面の表の最初の版（これより古い版は、抽出していない）。</summary>");
        w.Line($"public const string FirstVersion = \"{VersionOf(_history.Tags[0])}\";");
        w.Line();
        w.Line("/// <summary>API 面の表の最後の版（これより新しい版の変化は、生成に入っていない）。</summary>");
        w.Line($"public const string LatestVersion = \"{VersionOf(_history.LatestTag)}\";");
        w.Line();
        w.Line("/// <summary>生成の対象外にしたエンドポイント（キー → 理由）。</summary>");
        w.Open("public static IReadOnlyDictionary<string, string> Excluded { get; } = new Dictionary<string, string>(StringComparer.Ordinal)");
        foreach (var (key, reason) in _excluded)
        {
            w.Line($"[{CodeWriter.Literal(key)}] = {CodeWriter.Literal(reason)},");
        }

        w.Close(";");
        w.Close();
        return w.ToString();
    }
}
